effect.shader:
vec3 sat3v(vec3 c){ return clamp(c, vec3(0.0), vec3(1.0)); }
float lum(vec3 c){ return dot(c, vec3(0.2126, 0.7152, 0.0722)); }

// LAYER -> SCREEN. The height field is sampled through the layer transform, so
// the terrain is the layer's own picture and not the composition behind it.
// Positions are anchored on acScreenNorm - the engine's own screen position for
// this fragment - so the anchor never depends on the matrix. Only the DELTA goes
// through acLayerToScreen, and the w=0 multiply cancels the translation, so a
// layer-space offset becomes a screen-space offset exactly. fetchL(acLayerNorm)
// therefore returns texture2DCv(inputImg.texture, acScreenNorm), the engine idiom.
vec2 lpToScreen(vec2 v){ return acScreenNorm + (vec4(v - acLayerNorm, 0.0, 0.0) * acLayerToScreen).xy; }
vec4 fetchL(vec2 lp){ return texture2DCv(inputImg.texture, clamp(lpToScreen(lp), 0.0, 1.0)); }

// Luminance with the premultiply undone - a semi-transparent dark pixel would
// otherwise read as pure black and punch a hole in the terrain.
float lumL(vec2 lp){
vec4 s = fetchL(lp);
return lum(s.rgb / max(s.a, 1e-4));
}

// Height with an optional 5-tap average. Raw luminance is too noisy to shade:
// every compression artefact becomes a spike in the normal.
float hAt(vec2 lp, float r){
float s = lumL(lp);
if (preBlur > 0.001){
float d = r * preBlur * 2.0;
s += lumL(lp + vec2( d, 0.0));
s += lumL(lp + vec2(-d, 0.0));
s += lumL(lp + vec2(0.0,  d));
s += lumL(lp + vec2(0.0, -d));
s /= 5.0;
}
return s;
}

// Central-difference slope, in height units per layer unit.
vec2 hGrad(vec2 lp, float e){
float gx = hAt(lp + vec2(e, 0.0), e) - hAt(lp - vec2(e, 0.0), e);
float gy = hAt(lp + vec2(0.0, e), e) - hAt(lp - vec2(0.0, e), e);
return vec2(gx, gy) / (2.0 * e);
}

void main(){
vec2 lp  = acLayerNorm;
vec4 src = fetchL(lp);

float a  = max(src.a, 1e-4);
vec3 sc  = src.rgb / a;

float e  = 2.0 / max(acLayerSize.y, 1.0);

float h  = hAt(lp, e) * heightScale;
vec2  g  = hGrad(lp, e * 1.5) * heightScale;

// Surface normal. The z term is set by the height scale, so turning the scale
// up genuinely steepens the relief rather than just brightening it.
vec3 n = normalize(vec3(-g.x, -g.y, 1.0 / max(heightScale, 0.05)));

float la = radians(lightAngle);
float el = mix(0.15, 1.45, clamp(lightHeight, 0.0, 1.0));
vec3  L  = normalize(vec3(cos(la) * cos(el), sin(la) * cos(el), sin(el)));
float sh = clamp(dot(n, L), 0.0, 1.0);

vec3 c;
if (heightMode <= 0){
// Shaded Relief - slopes facing the sun go to paper, slopes facing away to ink.
c = mix(paperCol.rgb, inkCol.rgb, clamp(1.0 - sh, 0.0, 1.0) * reliefStrength);
} else if (heightMode <= 1){
// Contour Lines - distance to the nearest multiple of the spacing, measured
// from both sides so the line has the same width wherever it lands.
float st = max(contourStep, 0.005);
float f  = fract(h / st);
float d  = min(f, 1.0 - f);
float w  = max(contourWidth, 0.002);
float ln = 1.0 - smoothstep(w * 0.5, w, d);
c = mix(paperCol.rgb, inkCol.rgb, ln);
} else if (heightMode <= 2){
// Emboss - keep the picture and modulate it by the light. Cheapest mode and
// the one that reads best on text.
c = sc + (sh - 0.5) * reliefStrength;
} else if (heightMode <= 3){
// Normal Map - the raw normal as an RGB colour, ready to be used as a source.
c = n * 0.5 + vec3(0.5);
} else if (heightMode <= 4){
// Displace - actually move the pixels along the slope. This is the only mode
// that changes the layer's geometry rather than its shading.
vec2 dpos = lp + g * displace;
vec4 ds   = fetchL(dpos);
c = ds.rgb / max(ds.a, 1e-4);
} else {
// Slate Bands - quantise the terrain into flat layers and shade each one, so
// it reads as stacked rock rather than as a photograph.
float bands = floor(h * 8.0) / 8.0;
c = mix(paperCol.rgb, inkCol.rgb, clamp(bands, 0.0, 1.0));
c *= 0.55 + 0.75 * sh;
}

c = sat3v(c);
vec3  col = mix(sc, c, mixAmt);
float oA  = src.a * opacity;
gl_FragColor = vec4(col * oA, oA);
}
